from AlgorithmImports import *


class ExactStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.last_evaluated_date = None

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        current_date = self.Time.date()
        if self.last_evaluated_date == current_date:
            return
        self.last_evaluated_date = current_date

        self._update_market_state(data)

        if self.IsWarmingUp:
            return

        if not all(symbol in data.Bars for symbol in self.symbols.values()):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = float(data.Bars[self.spy].Close)
        spy_sma = float(self.spy_sma.Current.Value)
        aapl_rsi = float(self.aapl_rsi.Current.Value)

        spy_crosses_above = (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_previous_close <= self.spy_previous_sma
            and spy_close > spy_sma
        )

        spy_crosses_below = (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_previous_close >= self.spy_previous_sma
            and spy_close < spy_sma
        )

        if self.strategy_a_lot > 0 and spy_crosses_below:
            self._sell_lot(self.spy, self.strategy_a_lot, "Strategy A sell")
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and aapl_rsi > 60:
            self._sell_lot(self.aapl, self.strategy_b_lot, "Strategy B sell")
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            quantity = int(
                (self.Portfolio.TotalPortfolioValue * 0.40) / spy_close
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity, tag="Strategy A buy")
                self.strategy_a_lot += quantity

        if self.strategy_b_lot == 0 and self.Portfolio.Cash >= 20000:
            aapl_close = float(data.Bars[self.aapl].Close)
            quantity = int(20000 / aapl_close)
            if quantity > 0:
                self.MarketOrder(self.aapl, quantity, tag="Strategy B buy")
                self.strategy_b_lot += quantity

    def _update_market_state(self, data: Slice):
        if self.spy in data.Bars and self.spy_sma.IsReady:
            self.spy_previous_close = float(data.Bars[self.spy].Close)
            self.spy_previous_sma = float(self.spy_sma.Current.Value)

        if self.aapl in data.Bars:
            close = float(data.Bars[self.aapl].Close)

            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_previous_close = close

    def _sell_lot(self, symbol, quantity, tag):
        if quantity > 0:
            self.MarketOrder(symbol, -quantity, tag=tag)
